// Import TypeScript utility types here
import { Required, Partial, Pick, Record, Exclude } from 'typescript';

// Create the BaseProps interface here
interface BaseProps {
    title: string;
    description: string;
    imageUrl: string;
}

// Define the ExcludeOne helper type here
type ExcludeOne<T, K extends keyof T> = {
    [P in K]: Required<Pick<T, P>> & Partial<Record<Exclude<keyof T, K>, never>>;
}[K];

// Create the RequireOnlyOne type here
type RequireOnlyOne<T> = ExcludeOne<T, keyof T>;

// Create the test function here
function testRequireOnlyOne(props: RequireOnlyOne<BaseProps>) {
    console.log(props);
}

// Call the test function with a valid single property object here
testRequireOnlyOne({ title: 'Hello' });

// Call the test function with another valid single property object here
testRequireOnlyOne({ description: 'World' });

// Call the test function with multiple properties here
// testRequireOnlyOne({ title: 'Hello', description: 'World' }); // This should error

// Call the test function with no properties here
// testRequireOnlyOne({}); // This should error

// Create the Card component here
interface CardProps extends RequireOnlyOne<BaseProps> {
    className?: string;
}

function Card(props: CardProps) {
    const { className } = props;
    const content = 'title' in props ? props.title : 
                   'description' in props ? props.description : 
                   props.imageUrl;
    return (
        <div className={className}>
            <p>{content}</p>
        </div>
    );
}

// Render the Card component with valid props here
<Card title="Example Title" />;
